"""Show trigger failure settings, Lambda env, alert statuses and DLQ depth."""
from collections import Counter

from common.aws import client, resource


def alert_statuses():
    table, counts, kw = resource("dynamodb").Table("alerts"), Counter(), {}
    while True:
        r = table.scan(**kw)
        counts.update(i.get("status", "(old row, no status)") for i in r["Items"])
        if "LastEvaluatedKey" not in r:
            return dict(counts)
        kw["ExclusiveStartKey"] = r["LastEvaluatedKey"]


if __name__ == "__main__":
    lam = client("lambda")
    try:
        for m in lam.list_event_source_mappings(FunctionName="feature-updater")["EventSourceMappings"]:
            keys = ("State", "BisectBatchOnFunctionError", "MaximumRetryAttempts", "DestinationConfig")
            print("A4 trigger:", {k: m.get(k) for k in keys})
        print("A6 lambda env:", lam.get_function_configuration(FunctionName="feature-updater")["Environment"])
    except Exception as e:
        print("lambda: not found (poller mode?)", type(e).__name__)
    print("A2 alerts by status:", alert_statuses())        # expect only SENT, no PENDING
    try:
        sqs = client("sqs")
        url = sqs.get_queue_url(QueueName="feature-updater-dlq")["QueueUrl"]
        attrs = sqs.get_queue_attributes(QueueUrl=url, AttributeNames=["ApproximateNumberOfMessages"])
        print("A4 DLQ messages:", attrs["Attributes"]["ApproximateNumberOfMessages"])   # expect 0
    except Exception as e:
        print("A4 DLQ: not available", type(e).__name__)
